import os
import stripe

stripe.api_key = os.environ["STRIPE_API_KEY"]


def _build_charge_args(post_id, budget_cents, customer_id):
    return {
        "amount": budget_cents,
        "currency": "usd",
        "customer": customer_id,
        "description": f"Ad boost for post {post_id}",
        "metadata": {"post_id": post_id, "kind": "ad_boost"},
        "confirm": True,
        "off_session": True,
        "payment_method": _default_method(customer_id),
    }


def _default_method(customer_id):
    customer = stripe.Customer.retrieve(customer_id)
    return customer["invoice_settings"]["default_payment_method"]


def purchase_ad_boost(post_id: str, budget_cents: int, customer_id: str):
    if budget_cents <= 0:
        raise ValueError("budget_cents must be positive")
    args = _build_charge_args(post_id, budget_cents, customer_id)
    intent = stripe.PaymentIntent.create(**args)
    return {"payment_intent": intent.id, "status": intent.status, "amount": budget_cents}

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("social-ads")
API = "https://billing.internal.example.com/v1"


@mcp.tool()
def get_ad_account_balance_and_top_up(ad_account_id: str, min_balance_cents: int, top_up_cents: int) -> dict:
    if not ad_account_id:
        return {"error": "ad_account_id is required"}
    if min_balance_cents < 0 or top_up_cents <= 0:
        return {"error": "invalid amounts"}
    r = requests.get(f"{API}/ad-accounts/{ad_account_id}/balance", timeout=10)
    r.raise_for_status()
    balance = r.json()["balance_cents"]
    if balance >= min_balance_cents:
        return {"balance_cents": balance, "topped_up": False}
    c = requests.post(f"{API}/ad-accounts/{ad_account_id}/top-ups", json={"amount_cents": top_up_cents}, timeout=15)
    c.raise_for_status()
    return {"balance_cents": balance + top_up_cents, "topped_up": True}
